const d = $input.first().json ?? {};
const ex = d.execution ?? {};
const wf = d.workflow ?? {};
const err = ex.error ?? {};

const esc = (v) => String(v ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;');
const clip = (v, n) => {
  const s = String(v ?? '').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
};

const execId = ex.id ?? '';
const lines = [
  '⚠️ <b>WORKFLOW FAILED</b>',
  `<b>Workflow:</b> ${esc(wf.name || 'unknown')}`,
  `<b>Failed node:</b> ${esc(ex.lastNodeExecuted || 'unknown')}`,
  `<b>Error:</b> ${esc(clip(err.message || 'unknown error', 400))}`,
];
if (ex.mode) lines.push(`<b>Mode:</b> ${esc(ex.mode)}`);
lines.push(`<b>Execution:</b> ${esc(execId || 'n/a')}`);
if (ex.url) lines.push(`<b>Open:</b> ${esc(ex.url)}`);
const stack = clip(err.stack || '', 600);
if (stack) lines.push(`<b>Stack:</b>\n<pre>${esc(stack)}</pre>`);

return [{ json: { text: lines.join('\n') } }];
